from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]; h=len(g); w=len(g[0])
    axis=pos=None
    for r in range(h):
        if all(x==2 for x in g[r]): axis,pos='row',r; break
    if axis is None:
        for c in range(w):
            if all(g[r][c]==2 for r in range(h)): axis,pos='col',c; break
    if axis is None:return g
    cnt=Counter(x for row in g for x in row if x!=2); bg=cnt.most_common(1)[0][0]
    obj=max((x for x in cnt if x!=bg),key=lambda x:cnt[x])
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==obj]
    rlo=min(r for r,c in pts); rhi=max(r for r,c in pts); clo=min(c for r,c in pts); chi=max(c for r,c in pts)
    if axis=='row':
        sign=1 if rlo>pos else -1
        target=pos+sign*(rhi-rlo+1) if obj==6 else pos+sign*(chi-clo+2)
        if 0<=target<h:g[target]=[8]*w
    else:
        sign=1 if clo>pos else -1; target=pos+sign*(chi-clo+2)
        if 0<=target<w:
            for r in range(h):g[r][target]=8
    return g
